import{_ as t,b as l,c as i,g as n}from"./chunks/framework.86O3EbG5.js";const b=JSON.parse('{"title":"单词怪兽 · 角色原型","description":"","frontmatter":{},"headers":[],"relativePath":"public/word-zombie/characters.md","filePath":"public/word-zombie/characters.md"}'),r={name:"public/word-zombie/characters.md"};function s(e,o,g,d,a,c){return l(),i("div",null,[...o[0]||(o[0]=[n('<h1 id="单词怪兽-·-角色原型" tabindex="-1">单词怪兽 · 角色原型</h1><p>给后续出图 / 建模用的角色说明。画风、颜色和禁用项以本文为准。玩法见同目录 <a href="./prd.html">prd.md</a>。</p><p>这些角色都是<strong>练习本上的原创涂鸦</strong>，不是写实生物，也不是任何已有游戏的角色。</p><h2 id="出图总则" tabindex="-1">出图总则</h2><p><strong>画风</strong></p><ul><li>儿童蓝墨水圆珠笔 + 蜡笔填色，画在米色横线练习本上。</li><li>线条抖动、不闭合、粗细不匀，像孩子认真画的火柴人升级版。</li><li>圆角、软轮廓；眼睛是两点墨点，没有眼白、没有写实瞳孔。</li><li>正面或 3/4 侧面站立，全身入画，脚下留一点纸面。</li><li>背景：浅米色纸 <code>#f4efe2</code>，隐约蓝色横线 <code>#7aa3d4</code>。不要纯黑底、不要写实草地。</li></ul><p><strong>调色（尽量只用这些）</strong></p><table tabindex="0"><thead><tr><th>名称</th><th>色值</th><th>用途</th></tr></thead><tbody><tr><td>纸</td><td><code>#f4efe2</code></td><td>底、肤色浅填</td></tr><tr><td>蓝墨</td><td><code>#2b6cb0</code></td><td>主线、怪兽身体线</td></tr><tr><td>深蓝</td><td><code>#1e4a7a</code></td><td>眼睛、字</td></tr><tr><td>横线蓝</td><td><code>#7aa3d4</code></td><td>纸纹</td></tr><tr><td>橙</td><td><code>#e07a2f</code></td><td>屋顶、礼帽、披风点缀</td></tr><tr><td>绿</td><td><code>#3aa56a</code> / <code>#7ed957</code></td><td>豌豆、伞、鸟翅</td></tr></tbody></table><p><strong>统一道具：单词牌</strong></p><ul><li>怪兽头顶一块圆角小纸牌，蓝墨线框，浅奶油底 <code>#fffcf4</code>。</li><li><strong>认词</strong>：上排英文、下排中文。</li><li><strong>默写</strong>：只写中文，右上角可有小小的「默」。</li><li>出角色立绘时，牌上用占位词 <code>apple</code> / <code>苹果</code>，不要写真实商标。</li></ul><p><strong>禁用（非常重要）</strong></p><ul><li>不要马里奥、豌豆射手、僵尸、戴圆锥帽的花园僵尸、植物大战僵尸任何官方造型。</li><li>不要腐烂皮肉、鲜血、恐怖口器、武器、枪支。</li><li>不要写实照片、3D 次世代、日系厚涂美少女、表情包贴纸风。</li><li>怪兽是「拿错单词牌的纸上小怪物」，淘气、笨拙，不吓人。</li></ul><p><strong>建议出图规格</strong></p><ul><li>单角色：全身立绘，正方形或 3:4，透明底或练习本底各一版。</li><li>同一角色尽量同一套比例：头大、肢短，总高约 6 个头（豌豆和木屋除外）。</li><li>英文提示可复用文末「通用英文前缀」，再拼各角色英文短句。</li></ul><hr><h2 id="友好阵营" tabindex="-1">友好阵营</h2><h3 id="汤姆大叔" tabindex="-1">汤姆大叔</h3><ul><li><strong>身份</strong>：木屋里的老人，用中文短句给孩子打气。他自己不战斗。</li><li><strong>性格</strong>：温和、有点啰嗦、害怕屋顶漏雨，打对词会大声夸奖。</li><li><strong>外形</strong>：不是写实肖像。练习本简笔画老人：圆脸、两点眼、小小八字或弧线笑嘴；几笔白/灰乱发或半秃；圆鼻。穿宽松格子或素色家居衫，可有围裙。手可以插在门口向孩子挥手。</li><li><strong>比例</strong>：头略大，身子是圆梯形，比木屋矮半截。</li><li><strong>出图重点</strong>：和蔼、手绘、站在木屋门边或探出窗口；不要西部牛仔刻板印象，不要写实老人照片。</li></ul><h3 id="汤姆大叔的小木屋" tabindex="-1">汤姆大叔的小木屋</h3><ul><li><strong>身份</strong>：被保卫的家，HP 条对应这座屋子。</li><li><strong>外形</strong>：歪歪的单层童话小屋。墙填浅木色 <code>#f3e2c0</code>，门 <code>#d9c39a</code>，两扇浅蓝窗 <code>#cfe6f4</code>。屋顶是两笔橙墨折线，不对称。烟囱可有可无。屋脊上方可写「汤姆大叔」。</li><li><strong>气质</strong>：像孩子用尺子没画直的房子，可爱、不精致。</li><li><strong>出图重点</strong>：侧前方 3/4 视图；要能单独当场景资产，也要能和豌豆站在同一地面上。</li></ul><h3 id="豌豆-固定射手" tabindex="-1">豌豆（固定射手）</h3><ul><li><strong>身份</strong>：木屋右侧的守卫植株。玩家打对英文时，它从嘴边圆口喷出绿豌豆。打错会卡住约 1.2 秒，身子发灰、头上冒「…」。</li><li><strong>性格</strong>：紧张的好学生，想保护木屋，不会走路。</li><li><strong>外形（必须原创）</strong><ul><li>一根深绿色弯曲茎，扎在纸面草地上。</li><li>左右各一片浅绿色椭圆叶子。</li><li>主体是横椭圆的绿色豆荚头 <code>#7ed957</code>，不是人脸、不是辣椒、不是向日葵。</li><li>两点墨眼偏上；右侧一个短圆口（喷豆用），不是大炮管。</li><li>连击 3 次时整株微微发亮，可加一圈浅黄光，不要变成金属。</li></ul></li><li><strong>弹药</strong>：独立小资产「豌豆弹」——不规则小绿椭圆，蓝墨描边。</li><li><strong>出图重点</strong>：侧面朝右（怪兽从右边来）；僵直版可另出一张发灰、眼睛变成短横线。</li></ul><hr><h2 id="单词怪兽-共同规则" tabindex="-1">单词怪兽（共同规则）</h2><p>十二种都是「纸上墨水小怪物」。共用一张圆脸：椭圆头、两点眼、没有鼻子或只有一点。被瞄准时脸可微微泛浅蓝 <code>#e8f2ff</code>。</p><ul><li>都从画面<strong>右侧往左走</strong>，朝向木屋。</li><li>头上或略上方有单词牌（认词双行 / 默写单行）。</li><li>腿和胳膊是蓝墨折线，不要写实肌肉。</li><li>每种一个鲜明剪影，图鉴一眼能分清。</li><li>性格都偏喜剧：抢词、炫耀、迷路，不是要吃人。</li></ul><p>出图时每种给：<strong>全身立绘（无牌）</strong>、<strong>头顶认词牌</strong>、<strong>头顶默写牌</strong> 三套更好；至少要全身 + 认词牌一版。</p><hr><h3 id="_1-细腿怪-stick" tabindex="-1">1. 细腿怪 <code>stick</code></h3><ul><li><strong>一句话</strong>：最常见的单词怪兽，两条细腿走路。</li><li><strong>性格</strong>：普通、有点慌，像班里第一个举手又答错的同学。</li><li><strong>剪影</strong>：火柴人。细折线双腿、细腰、椭圆头、细胳膊前后摆。</li><li><strong>颜色</strong>：线蓝墨，头填纸色。</li><li><strong>动作</strong>：左右腿交错迈步，身体轻微前后晃。</li><li><strong>英文要点</strong>：skinny two-legged ink stick-figure monster, wobble walk, big oval head, tiny dot eyes, notebook doodle.</li></ul><h3 id="_2-高挑怪-tall" tabindex="-1">2. 高挑怪 <code>tall</code></h3><ul><li><strong>一句话</strong>：腿特别长，走得比别人快一截。</li><li><strong>性格</strong>：得意、爱俯视别人的牌子，其实头很小。</li><li><strong>剪影</strong>：同样火柴人，腿长约身体的 1.5 倍，头相对更小，整体瘦高。</li><li><strong>颜色</strong>：蓝墨线，纸色头。</li><li><strong>动作</strong>：大步走，胳膊甩得开。</li><li><strong>英文要点</strong>：very long thin legs, small head, tall stick monster, striding fast, doodle.</li></ul><h3 id="_3-圆滚怪-blob" tabindex="-1">3. 圆滚怪 <code>blob</code></h3><ul><li><strong>一句话</strong>：身子像一团墨水，挪得慢但很难忽略。</li><li><strong>性格</strong>：懒、黏糊，觉得自己是最圆的。</li><li><strong>剪影</strong>：矮胖；短短两腿；大椭圆身体；两侧伸出短触手。</li><li><strong>颜色</strong>：蓝墨线，身体浅纸色填，可有一点墨晕。</li><li><strong>动作</strong>：左右挪，触手轻轻甩。</li><li><strong>英文要点</strong>：round ink-blob body, short legs, stubby side arms, slow wobble, cute not scary.</li></ul><h3 id="_4-斗篷怪-cone" tabindex="-1">4. 斗篷怪 <code>cone</code></h3><ul><li><strong>一句话</strong>：套着三角斗篷，只露出一张圆脸。</li><li><strong>性格</strong>：害羞，躲在斗篷里偷看单词。</li><li><strong>剪影</strong>：正三角斗篷盖到脚，顶端露出圆脸。没有可见手臂。</li><li><strong>颜色</strong>：斗篷浅米 <code>#efe6d2</code>，蓝墨边，脸纸色。</li><li><strong>动作</strong>：斗篷下摆左右摆，像钟摆。</li><li><strong>注意</strong>：是软布三角斗篷，<strong>不是</strong>交通锥，<strong>不是</strong>花园僵尸的白色圆锥帽。</li><li><strong>英文要点</strong>：triangle cloth cloak covering body, only round face peeking on top, paper-cream cloak, NOT a traffic cone, NOT a garden zombie hat.</li></ul><h3 id="_5-礼帽怪-tophat" tabindex="-1">5. 礼帽怪 <code>tophat</code></h3><ul><li><strong>一句话</strong>：戴着歪礼帽，觉得自己很有派头。</li><li><strong>性格</strong>：爱炫耀，走两步要扶一下帽子。</li><li><strong>剪影</strong>：细腿怪身体 + 头上歪戴的橙/浅驼色高礼帽（宽帽檐 + 矮帽筒）。</li><li><strong>颜色</strong>：帽填 <code>#f3d0a8</code>，橙墨线 <code>#e07a2f</code>。</li><li><strong>动作</strong>：帽子随步伐左右倾斜。</li><li><strong>英文要点</strong>：doodle stick monster with a crooked tiny top hat, peach-orange hat, gentleman comic, not realistic Victorian.</li></ul><h3 id="_6-犄角怪-horns" tabindex="-1">6. 犄角怪 <code>horns</code></h3><ul><li><strong>一句话</strong>：头上两只小角，脾气比看起来大。</li><li><strong>性格</strong>：爱争第一，其实角只有两笔。</li><li><strong>剪影</strong>：细腿怪 + 头顶两只向外弯的小墨角。</li><li><strong>颜色</strong>：角与身体同蓝墨，不画成恶魔红。</li><li><strong>动作</strong>：低头用角指前方，像在较劲。</li><li><strong>英文要点</strong>：two small ink horns on a stick-figure head, comic stubborn, not a demon, not a bull.</li></ul><h3 id="_7-披风怪-cape" tabindex="-1">7. 披风怪 <code>cape</code></h3><ul><li><strong>一句话</strong>：身后拖着橙墨披风，跑起来呼呼响。</li><li><strong>性格</strong>：自以为是英雄，披风经常绊脚。</li><li><strong>剪影</strong>：细腿怪 + 背后一块张开的橙折线披风。</li><li><strong>颜色</strong>：披风只描橙线，或极浅橙填，不要变成超级英雄标志。</li><li><strong>动作</strong>：披风向右后方飘（因为向左走）。</li><li><strong>英文要点</strong>：orange ink cape flowing behind a doodle stick monster, playful hero wannabe, no logos.</li></ul><h3 id="_8-爬行怪-crawler" tabindex="-1">8. 爬行怪 <code>crawler</code></h3><ul><li><strong>一句话</strong>：好几条细腿轮流迈步，贴着纸面爬过来。</li><li><strong>性格</strong>：忙碌、认真，像在数自己的腿。</li><li><strong>剪影</strong>：扁椭圆身体贴地，四条以上折线细腿，圆脸抬得比身子高一点。</li><li><strong>颜色</strong>：蓝墨，身体纸色。</li><li><strong>动作</strong>：腿交替呈波浪。</li><li><strong>英文要点</strong>：low oval body, four spindly ink legs crawling, cute bug-like doodle, not a spider horror, not a cockroach photo.</li></ul><h3 id="_9-气球怪-balloon" tabindex="-1">9. 气球怪 <code>balloon</code></h3><ul><li><strong>一句话</strong>：身子像气球，用一根线拴着往前飘。</li><li><strong>性格</strong>：轻、恍惚，怕被风吹走。</li><li><strong>剪影</strong>：地面一根线，上面一个竖椭圆气球身，脸在气球上半。</li><li><strong>颜色</strong>：气球浅纸色 <code>#f7f0dc</code>，线蓝墨。</li><li><strong>动作</strong>：气球左右微晃，线拉成弧。</li><li><strong>英文要点</strong>：balloon-shaped body on a single string, floating doodle creature, oval head-body, not a party balloon brand.</li></ul><h3 id="_10-纸箱怪-crate" tabindex="-1">10. 纸箱怪 <code>crate</code></h3><ul><li><strong>一句话</strong>：套着涂鸦纸箱，走起来一顿一顿的。</li><li><strong>性格</strong>：闷、小心翼翼，从箱盖缝看路。</li><li><strong>剪影</strong>：短腿，身上一个竖长方形纸箱，中间一道横线像盖子缝；圆脸从箱顶露出。</li><li><strong>颜色</strong>：箱 <code>#efe2c4</code>，蓝墨线。</li><li><strong>动作</strong>：一顿一顿平移，像箱子在挪。</li><li><strong>英文要点</strong>：character wearing a cardboard box with a lid seam, face on top, short legs, doodle, not a robot, not a loot crate logo.</li></ul><h3 id="_11-鸟喙怪-beak" tabindex="-1">11. 鸟喙怪 <code>beak</code></h3><ul><li><strong>一句话</strong>：尖嘴加小翅膀，偶尔会跳着走。</li><li><strong>性格</strong>：急、爱插话，尖嘴先碰到牌子。</li><li><strong>剪影</strong>：细腿、小身子、圆脸右侧一个三角形尖嘴；左侧一小片绿翅膀。</li><li><strong>颜色</strong>：翅膀绿 <code>#3aa56a</code>，嘴与身体蓝墨。</li><li><strong>动作</strong>：微微离地跳跃，翅膀扇一下。</li><li><strong>英文要点</strong>：doodle bird-ish monster, tiny triangular beak, one small green wing, hop walk, not a realistic bird, not an angry bird.</li></ul><h3 id="_12-雨伞怪-umbrella" tabindex="-1">12. 雨伞怪 <code>umbrella</code></h3><ul><li><strong>一句话</strong>：举着一把绿伞，好像天随时会下雨。</li><li><strong>性格</strong>：谨慎、爱提醒别人「要下雨了」，伞比它高。</li><li><strong>剪影</strong>：细腿怪，右手（画面右侧）举起细杆，顶上扁椭圆绿伞面 <code>#d4edd4</code>。</li><li><strong>颜色</strong>：伞线绿，伞面浅绿填。</li><li><strong>动作</strong>：伞随步伐点头。</li><li><strong>英文要点</strong>：stick doodle holding a small green oval umbrella, cute, not a realistic fashion illustration.</li></ul><hr><h2 id="场景与其它资产-可选同批出图" tabindex="-1">场景与其它资产（可选同批出图）</h2><ul><li><strong>纸面草地</strong>：地面一条浅绿短竖线组成的草，不要 3D 草坪。</li><li><strong>练习本天空</strong>：就是横线纸，不要蓝天白云照片。</li><li><strong>墨水粘脚</strong>：连击 5 的特效——怪兽脚下一小摊浅蓝墨渍，像把鞋粘住。</li><li><strong>发光豌豆</strong>：连击 3——植株周围软软的浅光，手绘感，不要霓虹。</li></ul><hr><h2 id="给图像模型的通用英文前缀" tabindex="-1">给图像模型的通用英文前缀</h2><p>可直接复制，后面接上各角色「英文要点」：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>Children&#39;s ballpoint-pen doodle on cream lined notebook paper, wobbly uneven ink lines, simple filled shapes, comic-sans handmade look, two-dot eyes, no realistic shading, no 3D render, no photorealism. Palette: cream paper #f4efe2, blue ink #2b6cb0, orange #e07a2f, pea green #7ed957. Full body, centered, generous margin. Cute and slightly clumsy. Not Mario, not Plants vs Zombies, not a zombie, not a peashooter copy, no gore.</span></span></code></pre></div><p>负面提示建议：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span>photorealistic, 3D, cinematic lighting, horror, gore, rotten flesh, official game character, Mario, Luigi, peashooter, sunflower, conehead zombie, traffic cone hat, brand logo, weapon, gun, extra limbs mess, text watermark</span></span></code></pre></div>',61)])])}const p=t(r,[["render",s]]);export{b as __pageData,p as default};
